/// Compute the truncated length of an array of length `n` when
/// removing `m` elements. If `m >= n`, the result is 1. Otherwise it's `n - m`.
fn trunc_len(n: usize, m: usize) -> usize {
    if n > m {
        n - m
    } else {
        1
    }
}

/// Given a non-empty vector `c`, a non-negative integer `m`, and a float `scl`
/// (which is ignored in the truncation logic), produce a new vector according
/// to the rules:
/// - If `m == 0`, return `c` unchanged.
/// - If `m >= c.len()`, return a single-element vector `[c[0]]`.
/// - Otherwise, return the first `c.len() - m` elements.
fn legder(mut c: Vec<f64>, m: u8, _scl: f64) -> Vec<f64> {
    let n = c.len();
    let m_usize = m as usize;

    // If no truncation requested, return the original vector
    if m == 0 {
        return c;
    }

    // If we truncate away all or more elements than present, keep only the first
    if m_usize >= n {
        return vec![c[0]];
    }

    // Otherwise, take the first (n - m) elements
    let keep_len = trunc_len(n, m_usize);
    c.truncate(keep_len);
    c
}

